import { describe, expect, it } from 'vitest';
import { substituteTierUnion } from './generate_types.js';

const BANNER =
  '/* eslint-disable */\n/**\n * This file was automatically generated by json-schema-to-typescript.\n */\n\n';

describe('substituteTierUnion', () => {
  it('replaces the canonical tier union and injects the import once', () => {
    const source = `${BANNER}export interface C {\n  tier: 'personal' | 'confidential' | 'public';\n}\n`;
    const result = substituteTierUnion(source);
    expect(result).toContain('tier: StorageDataTier;');
    expect(result.match(/import type \{ StorageDataTier \}/g)).toHaveLength(1);
    expect(result.indexOf('import type')).toBeLessThan(result.indexOf('export interface'));
  });

  it('matches a differently ordered schema enum', () => {
    const source = `${BANNER}export interface C {\n  tier: 'public' | 'confidential' | 'personal';\n}\n`;
    expect(substituteTierUnion(source)).toContain('tier: StorageDataTier;');
  });

  it('substitutes inside type-alias declarations', () => {
    const source = `${BANNER}export type KnowledgeTier = 'personal' | 'confidential' | 'public';\n`;
    expect(substituteTierUnion(source)).toContain('export type KnowledgeTier = StorageDataTier;');
  });

  it('leaves longer unions containing the tier members untouched', () => {
    const source = `${BANNER}export interface C {\n  scope: 'personal' | 'confidential' | 'public' | 'system';\n}\n`;
    const result = substituteTierUnion(source);
    expect(result).toContain("'system'");
    expect(result).not.toContain('StorageDataTier');
  });

  it('is idempotent and does not double-inject the import', () => {
    const source = `${BANNER}export interface C {\n  tier: 'personal' | 'confidential' | 'public';\n}\n`;
    const once = substituteTierUnion(source);
    expect(substituteTierUnion(once)).toBe(once);
  });

  it('leaves content without the union unchanged', () => {
    const source = `${BANNER}export interface C {\n  mode: 'a' | 'b';\n}\n`;
    expect(substituteTierUnion(source)).toBe(source);
  });
});
